import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"配置详解","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/configuration.md","filePath":"modules/station/configuration.md","lastUpdated":0}`),a={name:`modules/station/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="配置详解" tabindex="-1">配置详解 <a class="header-anchor" href="#配置详解" aria-label="Permalink to “配置详解”">​</a></h1><p><code>plugins/EmakiStation/config.yml</code> 是主配置。<code>version</code> 是配置结构标记，插件按它合并新增的默认键；它与模块发布版本不同轨，不需要手工改成插件版本。</p><h2 id="顶层键" tabindex="-1">顶层键 <a class="header-anchor" href="#顶层键" aria-label="Permalink to “顶层键”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>&quot;1.0.8&quot;</code></td><td>配置结构版本标记，随默认资源同步维护。源码内部迁移常量另为 <code>1.0.2</code>，不要混用。</td></tr><tr><td><code>language</code></td><td><code>&quot;zh_CN&quot;</code></td><td>语言文件名，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td><code>true</code></td><td>首次启动时是否释放示例数据（<code>stations/</code>、<code>gui/</code>、<code>recipes/</code> 下的示例文件）。改为 false 后已存在文件不会被覆盖，也不会再补齐缺失示例。</td></tr></tbody></table><h2 id="queue-队列默认值" tabindex="-1"><code>queue</code> 队列默认值 <a class="header-anchor" href="#queue-队列默认值" aria-label="Permalink to “queue 队列默认值”">​</a></h2><p>每个工作站可以在自己的 <code>stations/&lt;id&gt;.yml</code> 里覆盖同名键。</p><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>base_length</code></td><td><code>3</code></td><td>基础队列长度。只有 <code>waiting</code> / <code>running</code> 占用长度，<code>pending_claim</code> 不占用。</td></tr><tr><td><code>permission_tiers</code></td><td><code>true</code></td><td>是否启用权限分级。启用后 <code>emakistation.queue.&lt;n&gt;</code> 中数字最大的一档生效。</td></tr><tr><td><code>max_length</code></td><td><code>32</code></td><td>权限分级后的硬上限，任何权限都不能突破。</td></tr><tr><td><code>progress_mode</code></td><td><code>&quot;offline&quot;</code></td><td>队首推进方式：<code>offline</code> 按真实时间推进，<code>online</code> 仅在玩家在线时累计。</td></tr><tr><td><code>cancel_refund_rate</code></td><td><code>1.0</code></td><td>取消队列条目时退还材料的比例（0.0 ~ 1.0）。</td></tr><tr><td><code>tick_interval</code></td><td><code>20</code></td><td>队列推进任务的间隔（tick）。全服只有这一个定时器。</td></tr><tr><td><code>speed_multiplier</code></td><td><code>1.0</code></td><td>全局配方耗时倍率。小于等于 0 时按 1.0 处理。</td></tr><tr><td><code>purchase.enabled</code></td><td><code>true</code></td><td>付费队列位全服总开关。</td></tr><tr><td><code>purchase.cost_file</code></td><td><code>&quot;queue_costs.yml&quot;</code></td><td>价格档位文件名，相对插件数据目录。</td></tr></tbody></table><p><code>pending_claim</code> 不占用队列长度是有意设计：否则背包和仓库同时满的玩家会被自己未领取的产物锁死队列。</p><p><code>cancel_refund_rate</code> 不按进度折算。串行单线队列里只有队首有进度，为一个几乎不存在的情况引入逐条目进度记账不值得，这是有意的简化。</p><p><code>progress_mode: offline</code> 只表示「计时继续」，不表示「离线发货」。EmakiStorage 拒绝对离线玩家做任何写操作，所以离线期间到点的条目只是「已到期」，真正结算发生在玩家下次上线时。</p><p>价格文件缺失、为空或没有任何可用价格时，购买一律被拒绝而不是免费放行。</p><h2 id="limits-容量上限" tabindex="-1"><code>limits</code> 容量上限 <a class="header-anchor" href="#limits-容量上限" aria-label="Permalink to “limits 容量上限”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>max_pending_claim</code></td><td><code>100</code></td><td>单个玩家最多累积多少条未领取产物。达到上限后拒绝新提交。</td></tr><tr><td><code>warn_material_types</code></td><td><code>50</code></td><td>单个配方材料种类数超过这个值时只记录警告，不阻止加载。</td></tr><tr><td><code>batch_multiplier_max</code></td><td><code>0</code></td><td>单次提交的最大倍率，<code>0</code> 表示不额外限制，仍受材料数量限制。</td></tr></tbody></table><p>配方材料种类数不受 GUI 槽位数限制，<code>warn_material_types</code> 只是防手滑。</p><h2 id="storage-仓库通道" tabindex="-1"><code>storage</code> 仓库通道 <a class="header-anchor" href="#storage-仓库通道" aria-label="Permalink to “storage 仓库通道”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>总开关。关闭后 EmakiStation 完全不调用 EmakiStorage。</td></tr><tr><td><code>batch_max_ops</code></td><td><code>200</code></td><td>单批最多多少个操作，与 EmakiStorage 的 <code>behavior.batch_max_ops</code> 对应。</td></tr></tbody></table><p>即使 <code>enabled</code> 为 true，仓库通道仍需要 EmakiStorage 提供 <code>emakistorage:atomic_batch</code> 能力才会启用。缺少该能力时<strong>不会</strong>退化为逐个 withdraw：那样会让材料在玩家背包里闪现一次，反而制造可利用的时间窗口。</p><p>材料同时来自背包和仓库时，插件优先使用 <code>emakistorage:reservation</code> 能力：先在仓库挂预留（不真正取出），再扣背包，最后提交预留。中途失败只需释放预留，而释放不会因为仓库容量不足而失败。EmakiStorage 版本较低、没有这个能力时，会退化为「先扣仓库、失败再存回」，存回本身可能因容量不足被拒，因此不如预留路径。</p><h2 id="persistence-持久化" tabindex="-1"><code>persistence</code> 持久化 <a class="header-anchor" href="#persistence-持久化" aria-label="Permalink to “persistence 持久化”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>autosave_interval_seconds</code></td><td><code>60</code></td><td>自动保存间隔（秒）。</td></tr><tr><td><code>save_on_submit</code></td><td><code>true</code></td><td>提交成功后是否立刻落盘，而不是等到下一次自动保存。</td></tr></tbody></table><p>队列文件里的条目对应「已经扣掉的材料」，所以这个间隔比仓库的自动保存更短。</p><p>队列文件和仓库文件是两份独立文件，硬崩溃仍可能让两者不一致（材料已扣但条目未存，或条目已存但扣料未落盘）。每个条目都完整记录了消耗清单，便于人工对账。彻底消除这个窗口需要跨插件两阶段提交，代价过高。</p><h2 id="gui-界面" tabindex="-1"><code>gui</code> 界面 <a class="header-anchor" href="#gui-界面" aria-label="Permalink to “gui 界面”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>click_throttle_ms</code></td><td><code>200</code></td><td>同一会话内两次点击的最小间隔（毫秒）。</td></tr><tr><td><code>refresh_interval_ticks</code></td><td><code>20</code></td><td>打开的界面多久重绘一次进度显示（tick）。</td></tr></tbody></table>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};